<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$op=(string)($_POST['operation']??'');$pdo=db();
try{
 if($op==='create_scale'){$name=trim((string)($_POST['name']??''));$level=(string)($_POST['level']??'');if($name===''||strlen($name)>100||!in_array($level,['O-Level','A-Level'],true))throw new DomainException('Enter a scale name and choose O-Level or A-Level.');$check=$pdo->prepare('SELECT COUNT(*) FROM grading_scales WHERE level=:level AND active=1');$check->execute(['level'=>$level]);$active=(int)$check->fetchColumn()?0:1;$stmt=$pdo->prepare('INSERT INTO grading_scales (name,level,active,created_by) VALUES (:name,:level,:active,:user)');$stmt->execute(['name'=>$name,'level'=>$level,'active'=>$active,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('grading.scale_created','grading_scales',$id,['level'=>$level,'active'=>(bool)$active]);$_SESSION['notice']='Grading scale created. Add its percentage bands.';header('Location: ../?page=academics&tab=grading&scale_id='.$id);exit;}
 $id=filter_var($_POST['scale_id']??null,FILTER_VALIDATE_INT);if(!$id)throw new DomainException('Select a valid grading scale.');
 if($op==='toggle_scale'){$active=(int)($_POST['active']??0)===1?1:0;$pdo->beginTransaction();$check=$pdo->prepare('SELECT level FROM grading_scales WHERE id=:id FOR UPDATE');$check->execute(['id'=>$id]);$level=$check->fetchColumn();if(!$level)throw new DomainException('Grading scale not found.');if($active){$off=$pdo->prepare('UPDATE grading_scales SET active=0 WHERE level=:level');$off->execute(['level'=>$level]);}$stmt=$pdo->prepare('UPDATE grading_scales SET active=:active WHERE id=:id');$stmt->execute(['active'=>$active,'id'=>$id]);audit_log('grading.scale_status_changed','grading_scales',$id,['active'=>(bool)$active]);$pdo->commit();$_SESSION['notice']='Grading scale status updated.';header('Location: ../?page=academics&tab=grading&scale_id='.$id);exit;}
 if($op!=='save_band')throw new DomainException('Unknown grading scale action.');$grade=trim((string)($_POST['grade']??''));$low=trim((string)($_POST['lower_percentage']??''));$high=trim((string)($_POST['upper_percentage']??''));$desc=trim((string)($_POST['description']??''));if($grade===''||strlen($grade)>16||!preg_match('/^\d{1,3}(?:\.\d{1,2})?$/',$low)||!preg_match('/^\d{1,3}(?:\.\d{1,2})?$/',$high)||(float)$low<0||(float)$high>100||(float)$low>(float)$high||strlen($desc)>120)throw new DomainException('Enter a grade and a valid percentage range between 0 and 100.');
 $pdo->beginTransaction();$scale=$pdo->prepare('SELECT id FROM grading_scales WHERE id=:id FOR UPDATE');$scale->execute(['id'=>$id]);if(!$scale->fetch())throw new DomainException('Grading scale not found.');$overlap=$pdo->prepare('SELECT COUNT(*) FROM grading_bands WHERE scale_id=:id AND lower_percentage<=:new_high AND upper_percentage>=:new_low');$overlap->execute(['id'=>$id,'new_high'=>number_format((float)$high,2,'.',''),'new_low'=>number_format((float)$low,2,'.','')]);if((int)$overlap->fetchColumn()>0)throw new DomainException('That percentage range overlaps an existing band.');$stmt=$pdo->prepare('INSERT INTO grading_bands (scale_id,grade,lower_percentage,upper_percentage,description) VALUES (:scale,:grade,:low,:high,:description)');$stmt->execute(['scale'=>$id,'grade'=>$grade,'low'=>number_format((float)$low,2,'.',''),'high'=>number_format((float)$high,2,'.',''),'description'=>$desc?:null]);$band=(int)$pdo->lastInsertId();audit_log('grading.band_created','grading_bands',$band,['scale_id'=>$id,'grade'=>$grade]);$pdo->commit();$_SESSION['notice']='Grade band saved.';header('Location: ../?page=academics&tab=grading&scale_id='.$id);exit;
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Grade scale save failed: '.$e->getMessage());$_SESSION['error']=$e->getCode()==='23000'?'That grading scale name or grade label already exists.':'Could not save the grading scale.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Grade scale save failed: '.$e->getMessage());$_SESSION['error']='Could not save the grading scale.';}
header('Location: ../?page=academics&tab=grading'.(!empty($id)?'&scale_id='.(int)$id:''));exit;
